Map courier = ctx._source.registry != null ? ctx._source.registry.courier : null;
if (courier == null) {
  ctx.op = 'noop';
  return;
}
if (courier.rated_at != null) {
  // nieczytelne stored rated_at: fail-open (stored = 0), ocena z rejestru wygrywa
  long stored = 0L;
  try {
    stored = java.time.ZonedDateTime.parse(courier.rated_at.toString()).toInstant().toEpochMilli();
  } catch (Exception e) {
    stored = 0L;
  }
  if (stored >= ((Number) params.rated_at_ms).longValue()) {
    ctx.op = 'noop';
    return;
  }
}
courier.on_time_rate = params.rate;
courier.rated_at = params.rated_at;
